// Create an octree container with the input points
XYZ::OctreePointC octree(std::span<const Point3D>(points));

// Prepare a vector to store the k nearest neighbors
std::vector<size_t> result_indices;

// If k is 0 or points is empty, return empty vector
if (k == 0 || points.empty()) {
    return result_indices;
}

// Use a priority queue to maintain the k nearest neighbors
// We will use a max-heap to keep the furthest of the k nearest neighbors on top
auto compare = [&searchPoint, &points](size_t lhs, size_t rhs) {
    auto dx_lhs = points[lhs].x - searchPoint.x;
    auto dy_lhs = points[lhs].y - searchPoint.y;
    auto dz_lhs = points[lhs].z - searchPoint.z;
    auto dist_lhs = dx_lhs * dx_lhs + dy_lhs * dy_lhs + dz_lhs * dz_lhs;

    auto dx_rhs = points[rhs].x - searchPoint.x;
    auto dy_rhs = points[rhs].y - searchPoint.y;
    auto dz_rhs = points[rhs].z - searchPoint.z;
    auto dist_rhs = dx_rhs * dx_rhs + dy_rhs * dy_rhs + dz_rhs * dz_rhs;

    return dist_lhs < dist_rhs; // Max-heap
};

std::priority_queue<size_t, std::vector<size_t>, decltype(compare)> pq(compare);

// Iterate through all points in the octree and find the k nearest neighbors
for (size_t i = 0; i < points.size(); ++i) {
    if (pq.size() < k) {
        pq.push(i);
    } else {
        // Calculate distances for both points
        auto dx_new = points[i].x - searchPoint.x;
        auto dy_new = points[i].y - searchPoint.y;
        auto dz_new = points[i].z - searchPoint.z;
        auto dist_new = dx_new * dx_new + dy_new * dy_new + dz_new * dz_new;

        auto dx_top = points[pq.top()].x - searchPoint.x;
        auto dy_top = points[pq.top()].y - searchPoint.y;
        auto dz_top = points[pq.top()].z - searchPoint.z;
        auto dist_top = dx_top * dx_top + dy_top * dy_top + dz_top * dz_top;

        if (dist_new < dist_top) {
            pq.pop();
            pq.push(i);
        }
    }
}

// Extract indices from the priority queue
while (!pq.empty()) {
    result_indices.push_back(pq.top());
    pq.pop();
}

// The result should be in ascending order of indices for consistency
std::sort(result_indices.begin(), result_indices.end());

return result_indices;

